import React, { useState } from 'react';
import { RESTAURANT_NAME } from '../constants';

const LogoSmall: React.FC = () => (
  <svg viewBox="0 0 100 100" className="w-8 h-8 md:w-10 md:h-10 text-orange-600 drop-shadow-sm" aria-hidden="true">
    <path 
