                  <p className="text-center text-stone-400 py-20 font-serif italic">Aucune commande enregistrée pour le moment.</p>
                ) : (
                  orders.map(order => (
                    <div key={order.id} className="p-6 border bg-white rounded-2xl flex justify-between items-center shadow-sm">
                      <div>
                        <h3 className="font-bold text-lg">{order.dishName} x{order.quantity}</h3>
                        <p className="text-sm text-stone-500">{order.customerName} - {order.customerPhone}</p>
                        <p className={`text-[10px] font-black uppercase mt-1 ${order.status === 'Payé' ? 'text-green-600' : 'text-orange-600'}`}>{order.status}</p>
                      </div>
                      <div className="flex gap-2">
                        <button onClick={() => setSelectedInvoice(order)} className="px-4 py-2 bg-stone-100 rounded-lg text-[10px] font-black uppercase hover:bg-stone-200">Facture</button>
                        {order.status === 'Nouveau' && (
                          <button onClick={() => updateOrderStatus(order.id, 'Payé')} className="px-4 py-2 bg-green-100 text-green-700 rounded-lg text-[10px] font-black uppercase hover:bg-green-200">Encaisser</button>
                        )}
                        <button onClick={() => deleteOrder(order.id)} className="p-2 text-red-500 hover:bg-red-50 rounded-lg" aria-label="Supprimer la commande">✕</button>
                      </div>
                    </div>
                  ))
                )}
              </div>
            )}

            {showAdminPortal === 'accounting' && (
              <div className="max-w-5xl mx-auto space-y-10">
                <div className="bg-stone-50 p-6 rounded-2xl border flex flex-wrap gap-4 items-end">
                   <div>
                      <label htmlFor="start-date" className="block text-[10px] font-black uppercase mb-1">Période du</label>
                      <input id="start-date" type="date" value={reportRange.start} onChange={e => setReportRange({...reportRange, start: e.target.value})} className="p-2 border rounded-lg text-sm" />
                   </div>
                   <div>
                      <label htmlFor="end-date" className="block text-[10px] font-black uppercase mb-1">Au</label>
                      <input id="end-date" type="date" value={reportRange.end} onChange={e => setReportRange({...reportRange, end: e.target.value})} className="p-2 border rounded-lg text-sm" />
                   </div>
                   <button onClick={handlePrint} className="bg-orange-600 text-white px-6 py-2.5 rounded-lg text-[10px] font-black uppercase hover:bg-orange-700">Imprimer le Rapport</button>
                </div>

                <div id="print-section" className="space-y-8">
                  <div className="hidden print:block text-center border-b pb-8 mb-8">
                    <h1 className="text-3xl font-serif font-bold">{RESTAURANT_NAME} - BILAN D'ACTIVITÉ</h1>
                    <p className="text-sm uppercase tracking-widest mt-2">Du {reportRange.start} au {reportRange.end}</p>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <div className="p-8 bg-stone-900 text-white rounded-3xl text-center">
                       <p className="text-[10px] font-black uppercase opacity-60 mb-2">Total Prévisionnel</p>
                       <p className="text-3xl font-serif italic text-orange-400">{stats.total.toLocaleString()} F</p>
                    </div>
                    <div className="p-8 bg-green-50 border border-green-100 rounded-3xl text-center">
                       <p className="text-[10px] font-black uppercase text-green-500 mb-2">Encaissements Réels</p>
                       <p className="text-3xl font-serif italic text-green-700">{stats.paid.toLocaleString()} F</p>
                    </div>
                    <div className="p-8 bg-orange-50 border border-orange-100 rounded-3xl text-center">
                       <p className="text-[10px] font-black uppercase text-orange-500 mb-2">À Percevoir</p>
                       <p className="text-3xl font-serif italic text-orange-700">{stats.pending.toLocaleString()} F</p>
                    </div>
                  </div>

                  <div className="overflow-x-auto bg-white rounded-2xl border">
                    <table className="w-full text-left text-sm" aria-label="Détail des transactions">
                      <thead className="border-b text-[10px] font-black uppercase text-stone-400">
                        <tr>
                          <th className="py-6 px-6">Date</th>
                          <th className="py-6 px-6">Client</th>
                          <th className="py-6 px-6">Plat</th>
                          <th className="py-6 px-6">Statut</th>
                          <th className="py-6 px-6 text-right">Montant</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y">
                        {filteredOrdersForReport.map(o => (
                          <tr key={o.id} className="hover:bg-stone-50 transition-colors">
                            <td className="py-4 px-6">{new Date(o.timestamp).toLocaleDateString()}</td>
                            <td className="py-4 px-6 font-bold">{o.customerName}</td>
                            <td className="py-4 px-6">{o.dishName} x{o.quantity}</td>
                            <td className="py-4 px-6 uppercase text-[9px] font-black">
                              <span className={o.status === 'Payé' ? 'text-green-600' : 'text-orange-600'}>{o.status}</span>
                            </td>
                            <td className="py-4 px-6 text-right font-bold">{(o.price * o.quantity).toLocaleString()} F</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>
            )}

            {showAdminPortal === 'menu_manager' && (
              <div className="grid gap-6 max-w-5xl mx-auto">
                {menuItems.map(dish => (
                  <div key={dish.id} className="p-6 bg-white border rounded-2xl flex flex-col md:flex-row gap-8 shadow-sm group">
                    <div className="relative w-full md:w-48 h-48 rounded-xl overflow-hidden bg-stone-100">
                      <img src={dish.image || "https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&q=80&w=400"} className="w-full h-full object-cover" alt="" />
                    </div>
                    <div className="flex-grow">
                        <div className="flex justify-between items-start mb-4">
                           <div>
                              <h3 className="text-xl font-bold text-stone-800">{dish.name}</h3>
                              <span className="inline-block px-3 py-1 bg-stone-100 text-stone-500 rounded-full text-[10px] font-black uppercase tracking-widest mt-1">{dish.category}</span>
                           </div>
                           <div className="text-xl font-serif font-bold text-orange-600">{dish.price.toLocaleString()} F</div>
                        </div>
                        <p className="text-stone-500 text-sm mb-6 leading-relaxed line-clamp-2">{dish.description}</p>
                        <div className="flex gap-4">
                           <button onClick={() => setEditingDish(dish)} className="px-6 py-2 border border-stone-200 rounded-xl text-[10px] font-black uppercase hover:bg-stone-50 transition">Modifier</button>
                           <button onClick={() => deleteDish(dish.id)} className="px-6 py-2 border border-red-100 text-red-500 rounded-xl text-[10px] font-black uppercase hover:bg-red-50 transition">Supprimer</button>
                        </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      )}

      {/* ADD / EDIT DISH MODAL */}
      {(showAddDishModal || editingDish) && (
        <div className="fixed inset-0 bg-stone-950/90 z-[400] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] p-10 max-w-xl w-full shadow-2xl relative overflow-y-auto max-h-[90vh]">
            <h2 className="text-2xl font-serif font-bold italic mb-8">{editingDish ? "Modifier le Plat" : "Ajouter au Menu"}</h2>

            <form onSubmit={saveDish} className="space-y-6">
               <div className="grid md:grid-cols-2 gap-6">
                  <div>
                     <label className="text-[10px] font-black uppercase text-stone-400 block mb-2 ml-1">Nom du Plat</label>
                     <input 
                        required 
                        type="text" 
                        value={editingDish ? editingDish.name : newDish.name} 
                        onChange={e => editingDish ? setEditingDish({...editingDish, name: e.target.value}) : setNewDish({...newDish, name: e.target.value})}
                        className="w-full p-4 bg-stone-50 border border-stone-100 rounded-2xl outline-none focus:ring-2 focus:ring-orange-500"
                        placeholder="Ex: Garba Royal"
                     />
                  </div>
                  <div>
                     <label className="text-[10px] font-black uppercase text-stone-400 block mb-2 ml-1">Prix (FCFA)</label>
                     <input 
                        required 
                        type="number" 
                        value={editingDish ? editingDish.price : newDish.price} 
                        onChange={e => editingDish ? setEditingDish({...editingDish, price: parseInt(e.target.value)}) : setNewDish({...newDish, price: parseInt(e.target.value)})}
                        className="w-full p-4 bg-stone-50 border border-stone-100 rounded-2xl outline-none focus:ring-2 focus:ring-orange-500"
                     />
                  </div>
               </div>

               <div>
                  <label className="text-[10px] font-black uppercase text-stone-400 block mb-2 ml-1">Catégorie</label>
                  <select 
                    className="w-full p-4 bg-stone-50 border border-stone-100 rounded-2xl outline-none focus:ring-2 focus:ring-orange-500"
                    value={editingDish ? editingDish.category : newDish.category}
                    onChange={e => editingDish ? setEditingDish({...editingDish, category: e.target.value as any}) : setNewDish({...newDish, category: e.target.value as any})}
                  >
                    <option value="entrée">Entrée</option>
                    <option value="plat">Plat de Résistance</option>
                    <option value="dessert">Dessert</option>
                    <option value="boisson">Boisson</option>
                  </select>
               </div>

               <div>
                  <label className="text-[10px] font-black uppercase text-stone-400 block mb-2 ml-1">Description</label>
                  <textarea 
                    rows={3}
                    required
                    value={editingDish ? editingDish.description : newDish.description}
                    onChange={e => editingDish ? setEditingDish({...editingDish, description: e.target.value}) : setNewDish({...newDish, description: e.target.value})}
                    className="w-full p-4 bg-stone-50 border border-stone-100 rounded-2xl outline-none focus:ring-2 focus:ring-orange-500 resize-none"
                    placeholder="Détails du plat, ingrédients principaux..."
                  />
               </div>

               <div>
                  <label className="text-[10px] font-black uppercase text-stone-400 block mb-2 ml-1">Image du Plat</label>
                  <div className="flex gap-4 items-center">
                    <div className="w-24 h-24 bg-stone-100 rounded-2xl overflow-hidden border border-dashed border-stone-300 flex items-center justify-center text-stone-400">
                      {(editingDish?.image || newDish.image) ? (
                        <img src={editingDish ? editingDish.image : newDish.image} className="w-full h-full object-cover" alt="" />
                      ) : (
                        <span className="text-2xl">+</span>
                      )}
                    </div>
                    <div className="flex-grow">
                       <input 
                         type="file" 
                         accept="image/*" 
                         ref={fileInputRef}
                         onChange={(e) => handleImageUpload(e, !!editingDish)}
                         className="hidden" 
                       />
                       <button 
                         type="button" 
                         onClick={() => fileInputRef.current?.click()}
                         className="w-full py-3 px-4 bg-white border border-stone-200 rounded-xl text-[10px] font-black uppercase hover:bg-stone-50 mb-2"
                       >
                         Choisir une image
                       </button>
                       <p className="text-[9px] text-stone-400 uppercase tracking-widest text-center">Format PNG, JPG (Max 5MB)</p>
                    </div>
                  </div>
               </div>

               <div className="flex gap-4 pt-4">
                  <button type="submit" className="flex-1 py-4 bg-stone-900 text-white rounded-2xl font-black uppercase text-xs tracking-[0.2em] hover:bg-orange-600 transition shadow-xl">
                    {editingDish ? "Enregistrer" : "Créer le plat"}
                  </button>
                  <button 
                    type="button" 
                    onClick={() => { setShowAddDishModal(false); setEditingDish(null); }}
                    className="flex-1 py-4 bg-stone-100 text-stone-500 rounded-2xl font-black uppercase text-xs tracking-[0.2em] hover:bg-stone-200 transition"
                  >
                    Annuler
                  </button>
               </div>
            </form>
          </div>
        </div>
      )}

      {/* INVOICE MODAL (FOR PRINTING) */}
      {selectedInvoice && (
        <div 
          className="fixed inset-0 bg-black/90 z-[400] flex items-center justify-center p-4 no-print"
          role="dialog"
          aria-modal="true"
        >
          <div className="bg-white rounded-[2rem] p-10 max-w-sm w-full shadow-2xl">
            <div id="print-section" className="text-stone-900 font-sans">
              <div className="text-center border-b pb-6 mb-6">
                <h1 className="text-2xl font-serif font-bold uppercase">{RESTAURANT_NAME}</h1>
                <p className="text-[9px] font-black uppercase text-stone-400">{LOCATION}</p>
                <p className="text-[10px] font-bold mt-1">{PHONE}</p>
              </div>
              <div className="mb-6 space-y-1">
                 <p className="text-[10px] font-black uppercase text-stone-400">FACTURE N° {selectedInvoice.id.slice(-6)}</p>
                 <p className="text-sm font-bold">Client : {selectedInvoice.customerName}</p>
                 <p className="text-xs">{new Date(selectedInvoice.timestamp).toLocaleString()}</p>
              </div>
              <div className="border-y py-4 mb-4 flex justify-between font-bold">
                 <span>{selectedInvoice.dishName} x{selectedInvoice.quantity}</span>
                 <span>{(selectedInvoice.price * selectedInvoice.quantity).toLocaleString()} F</span>
              </div>
              <div className="text-right mb-8">
                <p className="text-[10px] font-black uppercase text-stone-400">Total Net</p>
                <p className="text-2xl font-serif font-bold">{(selectedInvoice.price * selectedInvoice.quantity).toLocaleString()} FCFA</p>
              </div>
              <div className="text-center text-[9px] font-black uppercase text-stone-400">Merci de votre confiance !</div>
            </div>
            <div className="mt-8 flex gap-4">
              <button onClick={handlePrint} className="flex-1 bg-stone-900 text-white py-4 rounded-xl font-black text-xs">IMPRIMER</button>
              <button onClick={() => setSelectedInvoice(null)} className="flex-1 bg-stone-100 py-4 rounded-xl font-black text-xs">FERMER</button>
            </div>
          </div>
        </div>
      )}

      {/* LOGIN MODAL */}
      {showLoginModal && (
        <div 
          className="fixed inset-0 bg-stone-950/98 z-[500] flex items-center justify-center p-4"
          role="dialog"
          aria-modal="true"
        >
          <div className="bg-white rounded-[2rem] p-10 max-w-sm w-full shadow-2xl relative">
            <h2 className="text-xl font-bold font-serif italic text-center mb-6">Connexion Gérant</h2>
            <form onSubmit={handleLogin} className="space-y-4">
              <label htmlFor="admin-user" className="sr-only">Identifiant</label>
              <input id="admin-user" type="text" placeholder="Identifiant" value={username} onChange={e => setUsername(e.target.value)} className="w-full p-4 bg-stone-50 rounded-xl outline-none" required />

              <label htmlFor="admin-pass" className="sr-only">Mot de passe</label>
              <input id="admin-pass" type="password" placeholder="Mot de passe" value={password} onChange={e => setPassword(e.target.value)} className="w-full p-4 bg-stone-50 rounded-xl outline-none" required />

              {loginError && <p className="text-red-500 text-[10px] text-center font-bold" role="alert">{loginError}</p>}

              <button type="submit" className="w-full py-4 bg-stone-900 text-white rounded-xl font-black uppercase text-xs tracking-widest hover:bg-orange-600 transition-all">Connexion</button>
              <button type="button" onClick={() => setShowLoginModal(false)} className="w-full text-stone-400 text-[10px] font-black uppercase mt-2">Fermer</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import Navbar from './components/Navbar';
import MenuCard from './components/MenuCard';
import ReservationForm from './components/ReservationForm';
import { MENU_ITEMS as INITIAL_MENU, PHONE, LOCATION, RESTAURANT_NAME } from './constants';
import { Dish, OrderHistoryItem, Reservation } from './types';

const Logo: React.FC<{ className?: string }> = ({ className = "w-12 h-12" }) => (
  <div className={`relative flex items-center justify-center ${className}`} aria-hidden="true">
    <svg viewBox="0 0 100 100" className="w-full h-full drop-shadow-lg">
      <circle cx="50" cy="50" r="48" fill="none" stroke="currentColor" strokeWidth="1" className="text-orange-600/20" />
      <path d="M30 70 Q50 20 70 70 M50 35 L50 70" fill="none" stroke="currentColor" strokeWidth="6" strokeLinecap="round" className="text-orange-600" />
      <circle cx="50" cy="30" r="4" className="fill-orange-500 animate-pulse" />
      <path d="M40 75 H60" stroke="currentColor" strokeWidth="4" strokeLinecap="round" className="text-stone-800" />
    </svg>
  </div>
);

type AdminTab = 'none' | 'dashboard' | 'orders' | 'reservations' | 'accounting' | 'menu_manager';

const App: React.FC = () => {
  const [activeCategory, setActiveCategory] = useState<string>('tous');
  const [isAdminMode, setIsAdminMode] = useState<boolean>(false);
  const [showLoginModal, setShowLoginModal] = useState<boolean>(false);
  const [menuItems, setMenuItems] = useState<Dish[]>([]);
  const [showAdminPortal, setShowAdminPortal] = useState<AdminTab>('none');
  const [orders, setOrders] = useState<OrderHistoryItem[]>([]);
  const [reservations, setReservations] = useState<Reservation[]>([]);

  // Menu Management State
  const [showAddDishModal, setShowAddDishModal] = useState(false);
  const [editingDish, setEditingDish] = useState<Dish | null>(null);
  const [newDish, setNewDish] = useState<Partial<Dish>>({
    name: '',
    description: '',
    price: 0,
    category: 'plat',
    image: ''
  });

  const [selectedInvoice, setSelectedInvoice] = useState<OrderHistoryItem | null>(null);
  const [reportRange, setReportRange] = useState({ 
    start: new Date(new Date().setDate(new Date().getDate() - 30)).toISOString().split('T')[0], 
    end: new Date().toISOString().split('T')[0] 
  });

  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [loginError, setLoginError] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const localMenu = localStorage.getItem('grand_bassam_menu');
    const items = localMenu ? JSON.parse(localMenu) : INITIAL_MENU;
    setMenuItems(items);
    if (sessionStorage.getItem('is_admin') === 'true') {
      setIsAdminMode(true);
    }
    refreshAdminData();
  }, []);

  const refreshAdminData = () => {
    const fetchedOrders = JSON.parse(localStorage.getItem('grand_bassam_orders') || '[]');
    setOrders(fetchedOrders);
    const fetchedRes = JSON.parse(localStorage.getItem('grand_bassam_reservations') || '[]');
    setReservations(fetchedRes);
    const localMenu = localStorage.getItem('grand_bassam_menu');
    if (localMenu) setMenuItems(JSON.parse(localMenu));
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (username === 'admin' && password === 'bassam227') {
      setIsAdminMode(true);
      setShowLoginModal(false);
      sessionStorage.setItem('is_admin', 'true');
      setShowAdminPortal('dashboard');
      refreshAdminData();
    } else {
      setLoginError('Identifiants incorrects');
    }
  };

  const logoutAdmin = () => {
    setIsAdminMode(false);
    setShowAdminPortal('none');
    sessionStorage.removeItem('is_admin');
  };

  // Order Management
  const updateOrderStatus = (id: string, status: 'Payé' | 'Nouveau') => {
    const updated = orders.map(o => o.id === id ? { ...o, status } : o);
    setOrders(updated);
    localStorage.setItem('grand_bassam_orders', JSON.stringify(updated));
  };

  const deleteOrder = (id: string) => {
    if (confirm("Supprimer cette commande ?")) {
      const updated = orders.filter(o => o.id !== id);
      setOrders(updated);
      localStorage.setItem('grand_bassam_orders', JSON.stringify(updated));
    }
  };

  // Reservation Management
  const updateReservationStatus = (id: string, status: Reservation['status']) => {
    const updated = reservations.map(r => r.id === id ? { ...r, status } : r);
    setReservations(updated);
    localStorage.setItem('grand_bassam_reservations', JSON.stringify(updated));
  };

  const deleteReservation = (id: string) => {
    if (confirm("Supprimer cette réservation ?")) {
      const updated = reservations.filter(r => r.id !== id);
      setReservations(updated);
      localStorage.setItem('grand_bassam_reservations', JSON.stringify(updated));
    }
  };

  // Menu Management
  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, isEdit: boolean) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64 = reader.result as string;
        if (isEdit && editingDish) {
          setEditingDish({ ...editingDish, image: base64 });
        } else {
          setNewDish({ ...newDish, image: base64 });
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const saveDish = (e: React.FormEvent) => {
    e.preventDefault();
    let updatedMenu: Dish[];

    if (editingDish) {
      updatedMenu = menuItems.map(m => m.id === editingDish.id ? editingDish : m);
      setEditingDish(null);
    } else {
      const dishToSave: Dish = {
        ...newDish as Dish,
        id: Date.now().toString(),
      };
      updatedMenu = [dishToSave, ...menuItems];
      setNewDish({ name: '', description: '', price: 0, category: 'plat', image: '' });
      setShowAddDishModal(false);
    }

    setMenuItems(updatedMenu);
    localStorage.setItem('grand_bassam_menu', JSON.stringify(updatedMenu));
  };

  const deleteDish = (id: string) => {
    if (confirm("Supprimer ce plat définitivement ?")) {
      const updated = menuItems.filter(m => m.id !== id);
      setMenuItems(updated);
      localStorage.setItem('grand_bassam_menu', JSON.stringify(updated));
    }
  };

  const handlePrint = () => {
    window.print();
  };

  // Stats & Reports
  const filteredOrdersForReport = useMemo(() => {
    return orders.filter(o => {
      const orderDate = o.timestamp.split('T')[0];
      return orderDate >= reportRange.start && orderDate <= reportRange.end;
    });
  }, [orders, reportRange]);

  const stats = useMemo(() => {
    const total = filteredOrdersForReport.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);
    const paid = filteredOrdersForReport.filter(o => o.status === 'Payé').reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);
    return { total, paid, pending: total - paid };
  }, [filteredOrdersForReport]);

  const allActivities = useMemo(() => {
    const activityOrders = orders.map(o => ({ ...o, type: 'order' as const }));
    const activityReservations = reservations.map(r => ({ ...r, type: 'reservation' as const }));
    return [...activityOrders, ...activityReservations].sort((a, b) => 
      new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()
    );
  }, [orders, reservations]);

  const publicMenuItems = activeCategory === 'tous' ? menuItems : menuItems.filter(item => item.category === activeCategory);

  return (
    <div className="min-h-screen flex flex-col font-sans relative bg-stone-50">
      <style>{`
        @media print {
          body * { visibility: hidden !important; }
          #print-section, #print-section * { visibility: visible !important; }
          #print-section { position: absolute; left: 0; top: 0; width: 100%; padding: 0; background: white; color: black !important; }
          .no-print { display: none !important; }
          #print-section button { display: none !important; }
          .print-break-inside-avoid { break-inside: avoid; }
        }
        .custom-scrollbar::-webkit-scrollbar { width: 6px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #e5e7eb; border-radius: 10px; }
      `}</style>

