            </div>
          </section>

          {/* Menu Section */}
          <section id="menu" className="py-24 bg-stone-50">
            <div className="max-w-7xl mx-auto px-4 grid md:grid-cols-2 lg:grid-cols-3 gap-12">
              {publicMenuItems.map(dish => <MenuCard key={dish.id} dish={dish} />)}
