               </div>

               <div className="space-y-2">
                 <label className="text-[10px] font-black text-stone-400 uppercase tracking-widest">Description</label>
                 <textarea rows={4} required value={editingDish ? editingDish.description : newDish.description} onChange={e => editingDish ? setEditingDish({...editingDish, description: e.target.value}) : setNewDish({...newDish, description: e.target.value})} className="w-full p-5 bg-stone-50 border rounded-2xl text-sm italic" placeholder="Décrivez la magie du plat..." />
               </div>

               <div className="p-6 bg-stone-50 rounded-3xl border-2 border-dashed border-stone-200">
                  <div className="flex flex-col md:flex-row items-center gap-8">
                    <div className="w-32 h-32 bg-white rounded-3xl overflow-hidden shadow-inner flex items-center justify-center text-stone-200 shrink-0">
                       {(editingDish?.image || newDish.image) ? <img src={editingDish ? editingDish.image : newDish.image} className="w-full h-full object-cover" alt="Preview" /> : <span className="text-4xl">📸</span>}
                    </div>
                    <div className="flex-grow space-y-4">
                       <input type="file" accept="image/*" onChange={e => handleImageUpload(e, !!editingDish)} className="text-[10px] font-black uppercase text-stone-400 block w-full" />
                       {(editingDish?.image || newDish.image) && (
                         <button 
                           type="button" 
                           onClick={analyzeImage}
                           disabled={isAnalyzingImage}
                           className="bg-orange-600 text-white px-8 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl hover:bg-orange-700 transition disabled:opacity-50 flex items-center gap-2"
                         >
                           {isAnalyzingImage ? '...' : '✨ Analyse IA Gemini'}
                         </button>
                       )}
                    </div>
                  </div>
               </div>

               <div className="flex gap-4 pt-6">
                  <button type="submit" className="flex-grow bg-stone-900 text-white py-5 rounded-2xl font-black uppercase text-xs tracking-widest hover:bg-orange-600 transition-all">Sauvegarder</button>
                  <button type="button" onClick={() => { setShowAddDishModal(false); setEditingDish(null); }} className="px-10 bg-stone-100 text-stone-400 py-5 rounded-2xl font-black uppercase text-xs tracking-widest">Annuler</button>
               </div>
            </form>
          </div>
        </div>
      )}

      {/* INVOICE MODAL (Printable) */}
      {selectedInvoice && (
        <div className="fixed inset-0 bg-stone-950/95 z-[400] flex items-center justify-center p-4 no-print">
          <div className="bg-white rounded-[3rem] p-10 max-w-sm w-full shadow-2xl relative">
            <div id="print-section">
              <div className="text-center border-b pb-6 mb-6">
                <Logo className="w-12 h-12 mx-auto mb-2 text-orange-600" />
                <h1 className="text-xl font-serif font-bold uppercase tracking-tight">{RESTAURANT_NAME}</h1>
                <p className="text-[8px] font-black uppercase text-stone-400 mt-1">{LOCATION}</p>
                <p className="text-[10px] font-bold text-stone-800 mt-1">{PHONE}</p>
              </div>
              <div className="mb-6 space-y-1 text-xs">
                 <div className="flex justify-between"><span className="text-stone-400 uppercase">Facture N°</span><span className="font-bold">#GB{selectedInvoice.id.slice(-6)}</span></div>
                 <div className="flex justify-between"><span className="text-stone-400 uppercase">Client</span><span className="font-bold">{selectedInvoice.customerName}</span></div>
                 <div className="flex justify-between"><span className="text-stone-400 uppercase">Date</span><span className="font-bold">{new Date(selectedInvoice.timestamp).toLocaleDateString()}</span></div>
              </div>
              <div className="border-y py-4 mb-4 flex justify-between font-bold text-sm">
                 <span>{selectedInvoice.dishName} x{selectedInvoice.quantity}</span>
                 <span className="font-serif italic text-orange-600">{(selectedInvoice.price * selectedInvoice.quantity).toLocaleString()} F</span>
              </div>
              <div className="text-center pt-4">
                 <QRCodeImage size={60} className="opacity-10 mb-2" />
                 <p className="text-[8px] font-black uppercase text-stone-300 tracking-widest">Merci de votre visite !</p>
              </div>
            </div>
            <div className="mt-8 flex gap-4 no-print">
              <button onClick={() => window.print()} className="flex-1 bg-stone-900 text-white py-4 rounded-xl font-black text-[10px] uppercase shadow-xl">Imprimer</button>
              <button onClick={() => setSelectedInvoice(null)} className="flex-1 bg-stone-100 text-stone-400 py-4 rounded-xl font-black text-[10px] uppercase">Fermer</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

