                  <div className="flex -space-x-4">
                    {[1,2,3,4].map(i => <img key={i} className="w-12 h-12 rounded-full border-4 border-white object-cover" src={`https://i.pravatar.cc/150?img=${i+10}`} alt="Client" />)}
